        /// Stages a min-filter switch applied on `apply`. No GL call yet.
        /// Picks sampling when minified (one texel < one pixel): `.nearest`/`.linear`
        /// need no mipmaps and keep the texture complete; `*_mipmap_*` need generated
        /// mipmaps or sampling returns black. Pair with `setGenerateMipmap`.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - filter: Min filter (e.g. `.linear_mipmap_linear` for trilinear).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setMinFilter(self: *const Editor, filter: gl.textures.TextureMinFilter) *const Editor {
            @constCast(self)._pending_min_filter = filter;
            return @constCast(self);
        }
        /// Stages a mag-filter switch applied on `apply`. No GL call yet.
        /// Picks point (`.nearest`, pixelated) vs bilinear (`.linear`, smooth) when
        /// magnified (one texel > one pixel). Never needs mipmaps, unlike min filter.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - filter: Mag filter (`.nearest` or `.linear`).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setMagFilter(self: *const Editor, filter: gl.textures.TextureMagFilter) *const Editor {
            @constCast(self)._pending_mag_filter = filter;
            return @constCast(self);
        }
        /// Stages an S (U-axis) wrap switch applied on `apply`. No GL call yet.
        /// Units: governs normalized UV `0-1`; `.repeat` tiles ground/sprites,
        /// `.clamp_to_edge` stretches edge texels for UI/atlases (avoids bleeding),
        /// `.mirrored_repeat` mirrors tiling. Ignored when UV stays inside `0-1`.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - wrap: New wrap mode for S (U in `0-1` UV space).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setWrapS(self: *const Editor, wrap: gl.textures.TextureWrap) *const Editor {
            @constCast(self)._pending_wrap_s = wrap;
            return @constCast(self);
        }
        /// Stages a T (V-axis) wrap switch applied on `apply`. No GL call yet.
        /// Units: normalized UV `0-1`. See `setWrapS`; set both via `setWrap` for 2D.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - wrap: New wrap mode for T (V in `0-1` UV space).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setWrapT(self: *const Editor, wrap: gl.textures.TextureWrap) *const Editor {
            @constCast(self)._pending_wrap_t = wrap;
            return @constCast(self);
        }
        /// Stages an R (W-axis) wrap switch applied on `apply`. No GL call yet.
        /// Units: normalized depth UV `0-1`. Only matters for 3D/array sampling.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - wrap: New wrap mode for R (W in `0-1` UV space).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setWrapR(self: *const Editor, wrap: gl.textures.TextureWrap) *const Editor {
            @constCast(self)._pending_wrap_r = wrap;
            return @constCast(self);
        }
        /// Stages S+T wrap switches together. No GL call yet.
        /// Units: both in normalized UV `0-1`. Convenience for 2D sprites/tiles so
        /// both axes tile or clamp consistently; use `setWrapSTR` to include R.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - s: Wrap mode for S (U `0-1`).
        ///   - t: Wrap mode for T (V `0-1`).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setWrap(self: *const Editor, s: gl.textures.TextureWrap, t: gl.textures.TextureWrap) *const Editor {
            @constCast(self)._pending_wrap_s = s;
            @constCast(self)._pending_wrap_t = t;
            return @constCast(self);
        }
        /// Stages S+T+R wrap switches together. No GL call yet.
        /// Units: normalized UVW `0-1` each. Use for volumes/arrays where W must
        /// also tile or clamp; overkill for plain 2D (prefer `setWrap`).
        /// Parameters:
        ///   - self: Editor instance.
        ///   - s: Wrap mode for S.
        ///   - t: Wrap mode for T.
        ///   - r: Wrap mode for R.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setWrapSTR(self: *const Editor, s: gl.textures.TextureWrap, t: gl.textures.TextureWrap, r: gl.textures.TextureWrap) *const Editor {
            @constCast(self)._pending_wrap_s = s;
            @constCast(self)._pending_wrap_t = t;
            @constCast(self)._pending_wrap_r = r;
            return @constCast(self);
        }
        /// Stages a depth-compare mode switch applied on `apply`. No GL call yet.
        /// Use `.compare_ref_to_texture` for shadow-map depth textures so sampling
        /// returns a `0-1` visibility factor instead of raw depth; keep `.none`
        /// for color textures or depth visualization.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - mode: New comparison mode.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setCompareMode(self: *const Editor, mode: gl.textures.CompareMode) *const Editor {
            @constCast(self)._pending_compare_mode = mode;
            return @constCast(self);
        }
        /// Stages a depth-compare function applied on `apply`. No GL call yet.
        /// Picks shadow pass/fail rule (e.g. `.lequal`: fragment closer-or-equal to
        /// stored depth is lit). Ignored unless compare mode is enabled.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - func: New comparison function (e.g. `.lequal`).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setCompareFunc(self: *const Editor, func: gl.textures.CompareFunc) *const Editor {
            @constCast(self)._pending_compare_func = func;
            return @constCast(self);
        }
        /// Stages a base-level clamp applied on `apply`. No GL call yet.
        /// Units: mipmap index (`0` = full-size). Raise to skip the largest levels
        /// for streaming or perf; must stay `<= max_level`.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - level: New base level index.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setBaseLevel(self: *const Editor, level: i32) *const Editor {
            @constCast(self)._pending_base_level = level;
            return @constCast(self);
        }
        /// Stages a max-level clamp applied on `apply`. No GL call yet.
        /// Units: mipmap index. Lower to force blurrier/smaller levels (e.g. for
        /// distance fade); must stay `>= base_level`.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - level: New maximum level index.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setMaxLevel(self: *const Editor, level: i32) *const Editor {
            @constCast(self)._pending_max_level = level;
            return @constCast(self);
        }
        /// Stages a min-LOD clamp applied on `apply`. No GL call yet.
        /// Units: float LOD in mipmap levels (unitless, `0` = sharpest). Finer than
        /// integer `setBaseLevel`; use for LOD bias or smooth transitions.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - lod: New minimum LOD in levels.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setMinLod(self: *const Editor, lod: f32) *const Editor {
            @constCast(self)._pending_min_lod = lod;
            return @constCast(self);
        }
        /// Stages a max-LOD clamp applied on `apply`. No GL call yet.
        /// Units: float LOD in levels. Use to cap how blurry sampling may get.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - lod: New maximum LOD in levels.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setMaxLod(self: *const Editor, lod: f32) *const Editor {
            @constCast(self)._pending_max_lod = lod;
            return @constCast(self);
        }
        /// Stages a red-channel swizzle applied on `apply`. No GL call yet.
        /// Remaps what shader `.r` reads (e.g. force `.one` for opaque, `.red` to
        /// replicate luminance) without re-uploading texels. Use for format fixups.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - swizzle: New swizzle value for red.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setSwizzleR(self: *const Editor, swizzle: gl.textures.Swizzle) *const Editor {
            @constCast(self)._pending_swizzle_r = swizzle;
            return @constCast(self);
        }
        /// Stages a green-channel swizzle applied on `apply`. No GL call yet.
        /// See `setSwizzleR`.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - swizzle: New swizzle value for green.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setSwizzleG(self: *const Editor, swizzle: gl.textures.Swizzle) *const Editor {
            @constCast(self)._pending_swizzle_g = swizzle;
            return @constCast(self);
        }
        /// Stages a blue-channel swizzle applied on `apply`. No GL call yet.
        /// See `setSwizzleR`.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - swizzle: New swizzle value for blue.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setSwizzleB(self: *const Editor, swizzle: gl.textures.Swizzle) *const Editor {
            @constCast(self)._pending_swizzle_b = swizzle;
            return @constCast(self);
        }
        /// Stages an alpha-channel swizzle applied on `apply`. No GL call yet.
        /// See `setSwizzleR`; commonly forced to `.one` when source has no alpha.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - swizzle: New swizzle value for alpha.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setSwizzleA(self: *const Editor, swizzle: gl.textures.Swizzle) *const Editor {
            @constCast(self)._pending_swizzle_a = swizzle;
            return @constCast(self);
        }
        /// Stages all four channel swizzles at once. No GL call yet.
        /// Use to repack formats in one chain (e.g. `RRR1` luminance, `BGRA` fix).
        /// Parameters:
        ///   - self: Editor instance.
        ///   - r: Swizzle for red channel.
        ///   - g: Swizzle for green channel.
        ///   - b: Swizzle for blue channel.
        ///   - a: Swizzle for alpha channel.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setSwizzle(self: *const Editor, r: gl.textures.Swizzle, g: gl.textures.Swizzle, b: gl.textures.Swizzle, a: gl.textures.Swizzle) *const Editor {
            @constCast(self)._pending_swizzle_r = r;
            @constCast(self)._pending_swizzle_g = g;
            @constCast(self)._pending_swizzle_b = b;
            @constCast(self)._pending_swizzle_a = a;
            return @constCast(self);
        }
        /// Overrides the default auto mipmap behavior for next `apply`.
        /// By default any content upload (`setImage*/setStorage*/setSubImage*`,
        /// compressed, copy) auto-generates the mipmap chain so mipmap min filters
        /// stay complete; param-only edits never trigger it. Pass `false` to keep
        /// a single level (then use a non-mipmap min filter) or `true` to force.
        /// Parameters:
        ///   - self: Editor instance.
        ///   - gen: True to force generation, false to disable it even when
        ///     content is uploaded (default `null` means auto, see field docs).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setGenerateMipmap(self: *const Editor, gen: bool) *const Editor {
            @constCast(self)._pending_generate_mipmap = gen;
            return @constCast(self);
        }
        /// Stages a raw integer texture parameter (`glTexParameteri`) for `apply`.
        /// Escape hatch for enums this wrapper does not model; prefer typed
        /// `setMinFilter`/`setWrap*` etc when available so the CPU cache stays synced
        /// (this path does not update cached fields).
        /// Parameters:
        ///   - self: Editor instance.
        ///   - pname: Parameter name (unit depends on pname: enum, texels, or level).
        ///   - param: Integer value to set.
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setParameterI(self: *const Editor, pname: gl.textures.TextureParameter, param: i32) *const Editor {
            @constCast(self)._pending_param_i = .{ .pname = pname, .param = param };
            return @constCast(self);
        }
        /// Stages a raw float texture parameter (`glTexParameterf`) for `apply`.
        /// Escape hatch twin of `setParameterI`; use for float params like LOD clamps
        /// when the typed setter is insufficient. Units depend on `pname`
        /// (e.g. LOD in levels).
        /// Parameters:
        ///   - self: Editor instance.
        ///   - pname: Parameter name.
        ///   - param: Floating point value to set (e.g. LOD in levels).
        ///
        /// Returns:
        ///   - Pointer to the editor for chaining.
        pub fn setParameterF(self: *const Editor, pname: gl.textures.TextureParameter, param: f32) *const Editor {
            @constCast(self)._pending_param_f = .{ .pname = pname, .param = param };
            return @constCast(self);
        }

        /// Flushes the staged batch to GL in one bind. Activates the staged unit,
        /// allocates/uploads staged storage/image/sub-image/compressed/copy content
        /// (sizes in texels, copy sources in window pixels), applies staged sampler
        /// state (filters, UV `0-1` wraps, compare, level/LOD, swizzle), auto-generates
        /// mipmaps when content was uploaded unless opted out, syncs the CPU cache,
        /// and resets the editor for reuse. Call once per `edit()` chain.
        /// Parameters:
        ///   - self: Editor instance holding pending changes.
        ///
        /// Returns:
        ///   - void.
        pub fn apply(self: *const Editor) void {
            const m = @constCast(self)._texture.impl();
            const loaded = gl.loader.loaded();
            const effective_target = @constCast(self)._pending_target orelse m.target;
            if (@constCast(self)._pending_active_unit) |unit| {
                if (loaded) gl.textures.activeTexture(unit);
                m.active_unit = unit;
            }
            if (loaded) gl.textures.bind(effective_target, m.id);
            if (@constCast(self)._pending_target) |t| m.target = t;
            if (@constCast(self)._pending_storage2d) |s| {
                if (loaded) gl.textures.storage2d(s.target, s.levels, s.internalformat, s.width, s.height);
                m.internal_format = s.internalformat;
                m.width = s.width;
                m.height = s.height;
                m.levels = s.levels;
                m.target = s.target;
            }
            if (@constCast(self)._pending_storage3d) |s| {
                if (loaded) gl.textures.storage3d(s.target, s.levels, s.internalformat, s.width, s.height, s.depth);
                m.internal_format = s.internalformat;
                m.width = s.width;
                m.height = s.height;
                m.depth = s.depth;
                m.levels = s.levels;
                m.target = s.target;
            }
            if (@constCast(self)._pending_image2d) |i| {
                if (loaded) gl.textures.image2d(i.target, i.level, i.internalformat, i.width, i.height, i.border, i.format, i.kind, i.pixels);
                m.internal_format = i.internalformat;
                m.width = i.width;
                m.height = i.height;
                m.pixel_format = i.format;
                m.data_type = i.kind;
            }
            if (@constCast(self)._pending_image3d) |i| {
                if (loaded) gl.textures.image3d(i.target, i.level, i.internalformat, i.width, i.height, i.depth, i.border, i.format, i.kind, i.pixels);
                m.internal_format = i.internalformat;
                m.width = i.width;
                m.height = i.height;
                m.depth = i.depth;
                m.pixel_format = i.format;
                m.data_type = i.kind;
            }
            if (@constCast(self)._pending_sub2d) |s| if (loaded) gl.textures.subImage2d(s.target, s.level, s.xoffset, s.yoffset, s.width, s.height, s.format, s.kind, s.pixels);
            if (@constCast(self)._pending_sub3d) |s| if (loaded) gl.textures.subImage3d(s.target, s.level, s.xoffset, s.yoffset, s.zoffset, s.width, s.height, s.depth, s.format, s.kind, s.pixels);
            if (@constCast(self)._pending_compressed2d) |c| {
                if (loaded) gl.textures.compressedImage2d(c.target, c.level, c.internalformat, c.width, c.height, c.border, c.image_size, c.data);
                m.internal_format = c.internalformat;
                m.width = c.width;
                m.height = c.height;
            }
            if (@constCast(self)._pending_compressed3d) |c| {
                if (loaded) gl.textures.compressedImage3d(c.target, c.level, c.internalformat, c.width, c.height, c.depth, c.border, c.image_size, c.data);
                m.internal_format = c.internalformat;
                m.width = c.width;
                m.height = c.height;
                m.depth = c.depth;
            }
            if (@constCast(self)._pending_copy2d) |c| if (loaded) gl.textures.copyImage2d(c.target, c.level, c.internalformat, c.x, c.y, c.width, c.height, c.border);
            if (@constCast(self)._pending_copy_sub2d) |c| if (loaded) gl.textures.copySubImage2d(c.target, c.level, c.xoffset, c.yoffset, c.x, c.y, c.width, c.height);
            if (@constCast(self)._pending_copy_sub3d) |c| if (loaded) gl.textures.copySubImage3d(c.target, c.level, c.xoffset, c.yoffset, c.zoffset, c.x, c.y, c.width, c.height);
            if (@constCast(self)._pending_min_filter) |f| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_min_filter, @intCast(@intFromEnum(f)));
                m.min_filter = f;
            }
            if (@constCast(self)._pending_mag_filter) |f| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_mag_filter, @intCast(@intFromEnum(f)));
                m.mag_filter = f;
            }
            if (@constCast(self)._pending_wrap_s) |w| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_wrap_s, @intCast(@intFromEnum(w)));
                m.wrap_s = w;
            }
            if (@constCast(self)._pending_wrap_t) |w| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_wrap_t, @intCast(@intFromEnum(w)));
                m.wrap_t = w;
            }
            if (@constCast(self)._pending_wrap_r) |w| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_wrap_r, @intCast(@intFromEnum(w)));
                m.wrap_r = w;
            }
            if (@constCast(self)._pending_compare_mode) |v| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_compare_mode, @intCast(@intFromEnum(v)));
                m.compare_mode = v;
            }
            if (@constCast(self)._pending_compare_func) |v| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_compare_func, @intCast(@intFromEnum(v)));
                m.compare_func = v;
            }
            if (@constCast(self)._pending_base_level) |v| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_base_level, v);
                m.base_level = v;
            }
            if (@constCast(self)._pending_max_level) |v| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_max_level, v);
                m.max_level = v;
            }
            if (@constCast(self)._pending_min_lod) |v| {
                if (loaded) gl.textures.parameterF(effective_target, .texture_min_lod, v);
                m.min_lod = v;
            }
            if (@constCast(self)._pending_max_lod) |v| {
                if (loaded) gl.textures.parameterF(effective_target, .texture_max_lod, v);
                m.max_lod = v;
            }
            if (@constCast(self)._pending_swizzle_r) |s| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_swizzle_r, @intCast(@intFromEnum(s)));
                m.swizzle_r = s;
            }
            if (@constCast(self)._pending_swizzle_g) |s| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_swizzle_g, @intCast(@intFromEnum(s)));
                m.swizzle_g = s;
            }
            if (@constCast(self)._pending_swizzle_b) |s| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_swizzle_b, @intCast(@intFromEnum(s)));
                m.swizzle_b = s;
            }
            if (@constCast(self)._pending_swizzle_a) |s| {
                if (loaded) gl.textures.parameterI(effective_target, .texture_swizzle_a, @intCast(@intFromEnum(s)));
                m.swizzle_a = s;
            }
            if (@constCast(self)._pending_param_i) |p| if (loaded) gl.textures.parameterI(effective_target, p.pname, p.param);
            if (@constCast(self)._pending_param_f) |p| if (loaded) gl.textures.parameterF(effective_target, p.pname, p.param);
            // Auto mipmap default: any content upload in this batch completes
            // the mipmap chain unless explicitly opted out. Param-only edits
            // (filters, wrap, ...) never trigger generation on their own.
            const uploaded_content = @constCast(self)._pending_image2d != null or
                @constCast(self)._pending_image3d != null or
                @constCast(self)._pending_storage2d != null or
                @constCast(self)._pending_storage3d != null or
                @constCast(self)._pending_sub2d != null or
                @constCast(self)._pending_sub3d != null or
                @constCast(self)._pending_compressed2d != null or
                @constCast(self)._pending_compressed3d != null or
                @constCast(self)._pending_copy2d != null or
                @constCast(self)._pending_copy_sub2d != null or
                @constCast(self)._pending_copy_sub3d != null;
            const want_mipmap = @constCast(self)._pending_generate_mipmap orelse uploaded_content;
            if (want_mipmap) {
                if (loaded) gl.textures.generateMipmap(effective_target);
                m.has_mipmap = true;
            }
            @constCast(self).* = Editor.init(@constCast(self)._texture);
        }
    };
};

test "texture mipmaps auto-generated by default on content upload" {
    const allocator = std.testing.allocator;
    const tex = try Texture.create(allocator);
    defer tex.destroy(allocator);
    // Bare upload, no explicit setGenerateMipmap — auto default kicks in.
    tex.edit().setImage2D(.texture_2d, 0, .rgba8, 4, 4, 0, .rgba, .unsigned_byte, null).apply();
    try std.testing.expect(tex.getHasMipmap());

    const tex2 = try Texture.create(allocator);
    defer tex2.destroy(allocator);
    // Explicit opt-out is still respected.
    tex2.edit().setImage2D(.texture_2d, 0, .rgba8, 4, 4, 0, .rgba, .unsigned_byte, null).setGenerateMipmap(false).apply();
    try std.testing.expect(!tex2.getHasMipmap());

    const tex3 = try Texture.create(allocator);
    defer tex3.destroy(allocator);
    // Param-only edit uploads no content, so nothing is generated (no GL noise).
    tex3.edit().setMinFilter(.linear).apply();
    try std.testing.expect(!tex3.getHasMipmap());
}
